using Microsoft.AspNetCore.Mvc;

namespace Stoolball.Web.Validation
{
    public static class MvcOptionsExtensions
    {
        /// <summary>
        /// Makes the validation messages generated by data annotations and model binding use sentence case.
        /// </summary>
        public static void UseSentenceCaseValidationMessages(this MvcOptions options)
        {
            if (options is null)
            {
                throw new System.ArgumentNullException(nameof(options));
            }

            options.ModelMetadataDetailsProviders.Add(new SentenceCaseValidationMetadataProvider());

            // These messages are generated before any data annotation is checked, when the posted value cannot be converted to the type of the property.
            options.ModelBindingMessageProvider.SetValueMustBeANumberAccessor(
                displayName => $"The field {SentenceCase.ToMidSentence(displayName)} must be a number.");
            options.ModelBindingMessageProvider.SetAttemptedValueIsInvalidAccessor(
                (value, displayName) => $"The value '{value}' is not valid for {SentenceCase.ToMidSentence(displayName)}.");
        }
    }
}
